#[test]
fn unit_metadata() {
    let info = BitRate::<f64>::INFO;
    assert_eq!(info.name, "BitRate");
    assert_eq!(info.units.len(), BitRateUnit::ALL.len());
    for (&unit, unit_info) in BitRateUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, BitRateUnit::BitPerSecond.info());
}

